<?php get_header(); ?><section class="journal-shell"><header class="page-heading"><p class="eyebrow">NOTES FROM THE STUDIO</p><h1><?php if(is_home()) echo 'The journal'; elseif(is_search()) printf(esc_html__('Search: %s','atelier-salon'),esc_html(get_search_query())); else the_archive_title(); ?><span class="title-dot">.</span></h1><?php the_archive_description(); ?></header><div class="post-grid"><?php if(have_posts()): while(have_posts()): the_post(); ?><article <?php post_class('post-card'); ?>><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail()) the_post_thumbnail('large'); ?><span class="eyebrow"><?php echo esc_html(get_the_date()); ?></span><h2><?php the_title(); ?></h2></a><?php the_excerpt(); ?><a class="text-link" href="<?php the_permalink(); ?>">Read story ↗</a></article><?php endwhile; else: ?><p>Stories from the studio are coming soon.</p><?php endif; ?></div><?php the_posts_pagination(); ?></section><?php get_footer(); ?>